content.arguments:
{"description": "Create resvg render helper and test Chinese text", "command": "@'
const fs = require('fs');
const { Resvg } = require('@resvg/resvg-js');
const [,, inFile, outFile, widthArg] = process.argv;
const svg = fs.readFileSync(inFile, 'utf8');
const resvg = new Resvg(svg, {
  fitTo: { mode: 'width', value: Number(widthArg || 1024) },
  font: { loadSystemFonts: true, defaultFontFamily: 'Noto Sans SC' },
  background: 'rgba(0,0,0,0)'
});
const png = resvg.render().asPng();
fs.writeFileSync(outFile, png);
console.log(`wrote ${outFile} (${png.length} bytes)`);
'@ | Set-Content -Encoding utf8 ".\bingge-bbq\tools\render.js"
@'
<svg xmlns="http://www.w3.org/2000/svg" width="512" height="512" viewBox="0 0 512 512">
<rect width="512" height="512" fill="#4B5320"/><circle cx="256" cy="256" r="180" fill="#F4EBD8"/><text x="256" y="310" text-anchor="middle" font-family="Noto Sans SC Black" font-size="130" fill="#232B17">兵哥烧烤</text>
</svg>
'@ | Set-Content -Encoding utf8 ".\bingge-bbq\work\test.svg"
node ".\bingge-bbq\tools\render.js" ".\bingge-bbq\work\test.svg" ".\bingge-bbq\work\test.png" 512
Get-Item ".\bingge-bbq\work\test.png" | Select-Object FullName,Length"}

