{"description": "List Noto fonts and measure black weight", "command": "$py='C:\Users\24380\.dsh\dsh-runtimes\dsh-primary-runtime\dependencies\python\python.exe'
@'
from PIL import ImageFont
import glob, os
for p in glob.glob(r"C:\Windows\Fonts\*Noto*"):
    print(os.path.basename(p))
for p in glob.glob(r"C:\Windows\Fonts\*Noto*"):
    try:
        for w in (700,900):
            f = ImageFont.truetype(p, 140)
            try: f.set_variation_by_axes([w])
            except Exception: pass
            print(os.path.basename(p), w, f.getlength("兵哥烧烤"))
    except Exception as e:
        pass
'@ | Set-Content -Encoding utf8 ".\bingge-bbq\work\measure2.py"
& $py ".\bingge-bbq\work\measure2.py""}

