{"description": "Remove stale duplicate asset files after verification", "command": "$targets = @(
  ".\bingge-bbq\assets\logo-icon-char.svg",
  ".\bingge-bbq\assets\logo-mono.svg",
  ".\bingge-bbq\assets\logo-square-char.svg"
)
foreach ($t in $targets) {
  $item = Get-Item -LiteralPath $t -ErrorAction Stop
  if ($item.FullName -notlike "*\bingge-bbq\assets\*") { throw "Unexpected path: $($item.FullName)" }
  Write-Output "Removing $($item.FullName)"
  Remove-Item -LiteralPath $item.FullName -Force
}
Get-ChildItem ".\bingge-bbq\assets" -Recurse | ForEach-Object { $_.Name }"}

