{"description": "Validate README links and image dimensions", "command": "$py='C:\Users\24380\.dsh\dsh-runtimes\dsh-primary-runtime\dependencies\python\python.exe'
@'
import re, os
from PIL import Image
root = r".\bingge-bbq"
for rel in ("README.md", "shield/README.md", "source/README.md"):
    path = os.path.join(root, rel)
    text = open(path, encoding="utf-8").read()
    missing = []
    for label, target in re.findall(r"\[([^\]]+)\]\(([^)]+)\)", text):
        if target.startswith(("http://", "https://", "#")):
            continue
        p = os.path.normpath(os.path.join(os.path.dirname(path), target.replace("/", os.sep)))
        if not os.path.exists(p):
            missing.append((label, target))
    print(f"{rel}: missing {len(missing)}")
    for m in missing: print("  ", m)
print("--- images ---")
base = os.path.join(root, "shield", "png")
for name in sorted(os.listdir(base)):
    if name.lower().endswith((".png", ".jpg")):
        im = Image.open(os.path.join(base, name))
        print(f"{name:50} {im.size[0]}x{im.size[1]} {im.mode} {os.path.getsize(os.path.join(base,name))/1024:.0f}KB")
'@ | Set-Content -Encoding utf8 ".\bingge-bbq\qa.py"
& $py ".\bingge-bbq\qa.py"
Remove-Item -LiteralPath ".\bingge-bbq\qa.py" -Force"}

