content.arguments:
{"description": "Validate brush README links and clean work folder", "command": "$py='C:\Users\24380\.dsh\dsh-runtimes\dsh-primary-runtime\dependencies\python\python.exe'
@'
import re, os
root = r".\bingge-bbq"
for rel in ("README.md", "brush/README.md"):
    path = os.path.join(root, rel)
    text = open(path, encoding="utf-8").read()
    missing = []
    for label, target in re.findall(r"\[([^\]]+)\]\(([^)]+)\)", text):
        if target.startswith(("http://", "https://", "#")):
            continue
        p = os.path.normpath(os.path.join(os.path.dirname(path), target.replace("/", os.sep)))
        if not os.path.exists(p):
            missing.append((label, target))
    print(f"{rel}: missing {len(missing)}")
    for m in missing: print("  ", m)
'@ | Set-Content -Encoding utf8 ".\bingge-bbq\qa7.py"
& $py ".\bingge-bbq\qa7.py"
Remove-Item -LiteralPath ".\bingge-bbq\qa7.py" -Force
$root = (Resolve-Path ".\bingge-bbq").Path
$item = Get-Item -LiteralPath ".\bingge-bbq\work-brush" -ErrorAction Stop
if (-not $item.FullName.StartsWith($root + "\")) { throw "Unexpected path: $($item.FullName)" }
Remove-Item -LiteralPath $item.FullName -Recurse -Force
if (Test-Path ".\bingge-bbq\source\__pycache__") { Remove-Item -LiteralPath ".\bingge-bbq\source\__pycache__" -Recurse -Force }
Get-ChildItem ".\bingge-bbq" -Force | Select-Object Mode,Name"}

